-- [2026-10-28 06:35:46][Debug] Received raw data: {"type":"success","id":196,"result":{"realm":"c676e241-94e4-45bd-9b77-f825e8c50b81","type":"success","result":{"type":"string","value":"<html lang=\"en\"><head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Locator Landmark and Role Tests</title>\n  <style>\n    .span-button { display: inline-block; padding: 8px 18px; background: #e2e8f0; border: 1px solid #aaa; border-radius: 4px; cursor: pointer; margin-right: 6px; }\n    .link-button  { display: inline-block; padding: 8px 18px; background: #e2e8f0; border: 1px solid #aaa; border-radius: 4px; cursor: pointer; text-decoration: none; color: #333; }\n    .decorative-shape { width: 60px; height: 60px; background: linear-gradient(135deg,#f093fb,#f5576c); border-radius: 50%; display: inline-block; }\n  </style>\n</head>\n<body>\n\n  <!-- ── BANNER landmark (implicit role=banner via <header>) ── -->\n  <header auto-id=\"hdr-main\">\n    <h1>Landmark Role Test Page</h1>\n\n    <!-- ── NAVIGATION landmark – \"Main navigation\" ── -->\n    <nav aria-label=\"Main navigation\" auto-id=\"nav-main\">\n      <ul>\n        <li><a href=\"#section-personal\" auto-id=\"nav-main-personal\">Personal</a></li>\n        <li><a href=\"#section-contact\" auto-id=\"nav-main-contact\">Contact</a></li>\n      </ul>\n    </nav>\n  </header>\n\n  <!-- ── MAIN landmark ── -->\n  <main auto-id=\"main-content\">\n\n    <!-- FORM landmark – \"Mega test form\" -->\n    <form id=\"megaforma\" method=\"post\" action=\"#\" novalidate=\"\" aria-label=\"Mega test form\" auto-id=\"frm-mega\">\n\n      <!-- Section with HTML id for elmId \"section-personal\" test -->\n      <section id=\"section-personal\" auto-id=\"sec-personal\">\n        <h2>Personal Information</h2>\n\n        <!-- Several inputs with class \"text-input\" (class contains \"input\") for jsDisplay test -->\n        <input type=\"text\" class=\"text-input\" auto-id=\"edt-given-name\" value=\"Jane\">\n        <input type=\"text\" class=\"text-input\" auto-id=\"edt-family-name\" value=\"Smith\">\n        <input type=\"date\" class=\"text-input\" auto-id=\"edt-dob\" value=\"1990-06-15\">\n        <input type=\"email\" class=\"text-input\" auto-id=\"edt-email\" value=\"jane@example.com\">\n\n        <!-- aria-label on input – for textbox \"Nickname\" test -->\n        <input type=\"text\" aria-label=\"Nickname\" auto-id=\"edt-nickname\" class=\"text-input\" value=\"Jay\">\n      </section>\n\n      <!-- Checkbox with aria-label – for checkbox \"Read documents\" test -->\n      <div>\n        <input type=\"checkbox\" auto-id=\"chk-docs-read\" aria-label=\"Read documents\" checked=\"\">\n      </div>\n\n      <!-- Explicit role overrides -->\n      <div>\n        <span role=\"button\" tabindex=\"0\" auto-id=\"btn-span-role\" class=\"span-button\" aria-label=\"Span acting as button\">Span Button</span>\n\n        <a role=\"button\" href=\"#\" auto-id=\"btn-link-role\" class=\"link-button\" aria-label=\"Link acting as button\">Link-Button</a>\n\n        <div role=\"img\" auto-id=\"img-div-role\" aria-label=\"Abstract coloured shape\" class=\"decorative-shape\"></div>\n      </div>\n\n      <!-- HTML5 <search> element = role=\"search\" landmark -->\n      <search auto-id=\"srch-widget\">\n        <label for=\"site-search\">Site Search</label>\n        <input type=\"search\" id=\"site-search\" class=\"text-input\" aria-label=\"Search the site\">\n        <button type=\"button\">Search</button>\n      </search>\n\n      <!-- Submit button with aria-label – for button \"Submit the mega form\" test -->\n      <button type=\"submit\" auto-id=\"btn-submit\" class=\"text-input\" aria-label=\"Submit the mega form\">Submit</button>\n\n    </form>\n\n    <!-- ── Second NAVIGATION landmark – \"Breadcrumb\" (needed for multi-element Navigation test) ── -->\n    <nav aria-label=\"Breadcrumb\" auto-id=\"nav-breadcrumb\">\n      <ol>\n        <li><a href=\"#\">Home</a></li>\n        <li><span aria-current=\"page\">Tests</span></li>\n      </ol>\n    </nav>\n\n  </main>\n\n  <!-- ── COMPLEMENTARY landmark – \"Help and tips\" ── -->\n  <aside aria-label=\"Help and tips\" auto-id=\"aside-help\">\n    <h2>Form Help</h2>\n    <p>Fields marked <strong>*</strong> are required.</p>\n  </aside>\n\n  <!-- ── CONTENTINFO landmark (implicit via <footer>) ── -->\n  <footer auto-id=\"ftr-main\">\n    <p>© 2026 Landmark Role Test Page. For testing purposes only.</p>\n  </footer>\n\n\n\n</body></html>"}}}
